use crate::logic;

extern "C" {
    fn putchar(c: i32) -> i32;
    fn srand(seed: u32);
    fn rand() -> i32;
}

pub fn put_byte(b: u8) {
    unsafe { putchar(b as i32); }
}

pub fn output_message(result: u32, choice: u32) {
    let message = match choice {
        0 => format!("Result: {} — The number is as calm as a sleeping sloth.\n", result),
        1 => format!("Result: {} — It tried to divide by zero but thought better of it.\n", result),
        2 => format!("Result: {} — Secretly wishes it was a float.\n", result),
        3 => format!("Result: {} — Built entirely from left shifts and dreams.\n", result),
        4 => format!("Result: {} — Bitwise ANDed its way into your heart.\n", result),
        5 => format!("Result: {} — XOR marks the spot.\n", result),
        6 => format!("Result: {} — Practically a math meme at this point.\n", result),
        7 => format!("Result: {} — Stronger than a C macro on Monday morning.\n", result),
        8 => format!("Result: {} — Thinks it's the boss of all unsigned ints.\n", result),
        9 => format!("Result: {} — May contain traces of peanuts and logic gates.\n", result),
        _ => format!("Result: {} — How did we even get here?\n", result),
    };

    for &b in message.as_bytes() {
        put_byte(b);
    }
}

#[no_mangle]
pub unsafe extern "C" fn perform_operations(a: u32, b: u32) -> u32 {
    logic::perform_operations(a, b)
}

#[no_mangle]
pub unsafe extern "C" fn switch_arith(seed: u32) {
    srand(seed);
    let a = rand() as u32;
    let b = rand() as u32;
    let result = logic::perform_operations(a, b);
    let choice = result % 10;
    output_message(result, choice);
}
